    /**
     * Tests getting all DataCategorys.
     *
     * @return    Collection
     */
    public List<DataCategory> testGetAll() throws Throwable {
    LOGGER.info( "DataCategoryTest:testGetAll() - Retrieving Collection of DataCategorys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DataCategory : " );
    List<DataCategory> collection  = null;

    try {
        // call the static get method on the DataCategoryService
        collection = service.getAllDataCategory();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DataCategory currEntity  = null;
            Iterator<DataCategory> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDataCategoryId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

